xinshengCustomCss:
/* --- 1. 引入小学生可爱手写字体 --- */
@import url('https://fonts.googleapis.com/css2?family=ZCOOL+KuaiLe&display=swap');

/* --- 2. 全局信纸背景与重置 (恢复圆角 + 页面微拉宽) --- */
.xt-root {
    --xt-bg: #fdfdfd !important;
    font-family: 'ZCOOL KuaiLe', "Chalkboard SE", "Comic Sans MS", cursive, sans-serif !important;
    padding: 0 !important;
    margin: 0 -4px !important; /* 微调页面拉宽，更舒展 */
    width: calc(100% + 8px) !important;

    background-color: var(--xt-bg) !important;
    border-radius: 12px !important; /* 恢复好看的手账圆角 */
    box-shadow: 0 4px 20px rgba(0,0,0,0.06) !important; 

    /* 铺满全屏的虚线信纸背景，严格 40px 一行 */
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg%20width%3D%27100%25%27%20height%3D%2740%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Cline%20x1%3D%270%27%20y1%3D%2739%27%20x2%3D%272000%27%20y2%3D%2739%27%20stroke%3D%27%23d0d0d0%27%20stroke-width%3D%271.5%27%20stroke-dasharray%3D%278%,6%27%2F%3E%3C%2Fsvg%3E") !important;
    background-size: 100% 40px !important;

    /* 【神级对齐】11px偏移量，完美托住汉字的底部基线！ */
    background-position: 0 11px !important; 
}

/* 抹除默认文本的框线 */
.xt-text { background: transparent !important; border: none !important; margin: 0 !important; font-style: normal !important; display: block !important; }

/* --- 3. 顶栏伪装工具条 (固定 50px 高度，带纯实线底部边界) --- */
.xt-text-sysToolbar {
    height: 50px !important; 
    box-sizing: border-box !important;
    background-color: #fdfdfd !important;
    /* 高亮的纯实线边界，利用 z-index 压住底层背景 */
    border-bottom: 1.5px solid #c8c8c8 !important; 
    position: relative !important;
    z-index: 10 !important;
}
/* 左侧：32px 返回箭头 (纯直线段) */
.xt-text-sysToolbar::before {
    content: ""; position: absolute; left: 16px; top: 9px; width: 32px; height: 32px;
    background: url("data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%234a68d6%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22square%22%20stroke-linejoin%3D%22miter%22%3E%3Cpolyline%20points%3D%2215%2018%209%2012%2015%206%22%2F%3E%3C%2Fsvg%3E") center/contain no-repeat;
}

/* 右侧：32px 大图标，【解决边缘被裁切问题】 */
.xt-text-sysToolbar::after {
    content: ""; position: absolute; right: 12px; top: 9px; 

    /* 【第一步】：容器总宽度向左再延伸 3px (286 + 3 = 289px)，彻底包住第一个图标 */
    width: 289px !important; 
    height: 32px; 

    background-image: 
        /* 1. 黑: 键盘 */
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20viewBox%3D%270%200%2032%2032%27%20fill%3D%27none%27%20stroke%3D%27%23333%27%20stroke-width%3D%271.5%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Crect%20x%3D%272%27%20y%3D%272%27%20width%3D%2728%27%20height%3D%2728%27%20rx%3D%276%27%2F%3E%3Crect%20x%3D%277%27%20y%3D%2710%27%20width%3D%2718%27%20height%3D%2712%27%20rx%3D%272%27%2F%3E%3Ccircle%20cx%3D%2710%27%20cy%3D%2714%27%20r%3D%271%27%20fill%3D%27%23333%27%20stroke%3D%27none%27%2F%3E%3Ccircle%20cx%3D%2716%27%20cy%3D%2714%27%20r%3D%271%27%20fill%3D%27%23333%27%20stroke%3D%27none%27%2F%3E%3Ccircle%20cx%3D%2722%27%20cy%3D%2714%27%20r%3D%271%27%20fill%3D%27%23333%27%20stroke%3D%27none%27%2F%3E%3Cline%20x1%3D%2710%27%20y1%3D%2718%27%20x2%3D%2722%27%20y2%3D%2718%27%2F%3E%3C%2Fsvg%3E"),
        /* 2. 黑: 铅笔带底线 */
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20viewBox%3D%270%200%2032%2032%27%20fill%3D%27none%27%20stroke%3D%27%23333%27%20stroke-width%3D%271.5%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Crect%20x%3D%272%27%20y%3D%272%27%20width%3D%2728%27%20height%3D%2728%27%20rx%3D%276%27%2F%3E%3Cpath%20d%3D%27M19%209l4%204-11%2011-4%201%201-4z%27%20stroke-linejoin%3D%27round%27%2F%3E%3Cline%20x1%3D%278%27%20y1%3D%2723%27%20x2%3D%2724%27%20y2%3D%2723%27%20stroke-linecap%3D%27round%27%2F%3E%3C%2Fsvg%3E"),
        /* 3. 青蓝: 波浪 */
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20viewBox%3D%270%200%2032%2032%27%20fill%3D%27none%27%20stroke%3D%27%237bc2c0%27%20stroke-width%3D%271.5%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Ccircle%20cx%3D%2716%27%20cy%3D%2716%27%20r%3D%2714%27%2F%3E%3Cpath%20d%3D%27M8%2016c2.5-3.5%205-3.5%208%200s5.5%203.5%208%200%27%20stroke-linecap%3D%27round%27%2F%3E%3C%2Fsvg%3E"),
        /* 4. 青蓝: 风景 */
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20viewBox%3D%270%200%2032%2032%27%20fill%3D%27none%27%20stroke%3D%27%237bc2c0%27%20stroke-width%3D%271.5%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Ccircle%20cx%3D%2716%27%20cy%3D%2716%27%20r%3D%2714%27%2F%3E%3Crect%20x%3D%277%27%20y%3D%2710%27%20width%3D%2718%27%20height%3D%2712%27%20rx%3D%271.5%27%2F%3E%3Cpath%20d%3D%27M7%2018l4-4%203%203%203-3%204%204%27%20stroke-linejoin%3D%27round%27%2F%3E%3Ccircle%20cx%3D%2719%27%20cy%3D%2714%27%20r%3D%271.5%27%20fill%3D%27%237bc2c0%27%20stroke%3D%27none%27%2F%3E%3C%2Fsvg%3E"),
        /* 5. 青蓝: 麦克风 */
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20viewBox%3D%270%200%2032%2032%27%20fill%3D%27none%27%20stroke%3D%27%237bc2c0%27%20stroke-width%3D%271.5%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Ccircle%20cx%3D%2716%27%20cy%3D%2716%27%20r%3D%2714%27%2F%3E%3Crect%20x%3D%2713%27%20y%3D%278%27%20width%3D%276%27%20height%3D%2710%27%20rx%3D%273%27%2F%3E%3Cpath%20d%3D%27M9%2015v2a7%207%200%200014%200v-2M16%2024v4M12%2028h8%27%20stroke-linecap%3D%27round%27%2F%3E%3C%2Fsvg%3E"),
        /* 6. 黑: 文档 */
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20viewBox%3D%270%200%2032%2032%27%20fill%3D%27none%27%20stroke%3D%27%23333%27%20stroke-width%3D%271.5%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Crect%20x%3D%272%27%20y%3D%272%27%20width%3D%2728%27%20height%3D%2728%27%20rx%3D%276%27%2F%3E%3Crect%20x%3D%279%27%20y%3D%276%27%20width%3D%2714%27%20height%3D%2720%27%20rx%3D%271.5%27%2F%3E%3Cline%20x1%3D%2712%27%20y1%3D%2711%27%20x2%3D%2720%27%20y2%3D%2711%27%2F%3E%3Cline%20x1%3D%2712%27%20y1%3D%2716%27%20x2%3D%2720%27%20y2%3D%2716%27%2F%3E%3Cline%20x1%3D%2712%27%20y1%3D%2721%27%20x2%3D%2717%27%20y2%3D%2721%27%2F%3E%3C%2Fsvg%3E"),
        /* 7. 黑: 列表 */
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20viewBox%3D%270%200%2032%2032%27%20fill%3D%27none%27%20stroke%3D%27%23333%27%20stroke-width%3D%271.5%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Crect%20x%3D%272%27%20y%3D%272%27%20width%3D%2728%27%20height%3D%2728%27%20rx%3D%276%27%2F%3E%3Cline%20x1%3D%2713%27%20y1%3D%2710%27%20x2%3D%2724%27%20y2%3D%2710%27%20stroke-linecap%3D%27round%27%2F%3E%3Cline%20x1%3D%2713%27%20y1%3D%2716%27%20x2%3D%2724%27%20y2%3D%2716%27%20stroke-linecap%3D%27round%27%2F%3E%3Cline%20x1%3D%2713%27%20y1%3D%2722%27%20x2%3D%2724%27%20y2%3D%2722%27%20stroke-linecap%3D%27round%27%2F%3E%3Ccircle%20cx%3D%278%27%20cy%3D%2710%27%20r%3D%271.5%27%20fill%3D%27%23333%27%20stroke%3D%27none%27%2F%3E%3Ccircle%20cx%3D%278%27%20cy%3D%2716%27%20r%3D%271.5%27%20fill%3D%27%23333%27%20stroke%3D%27none%27%2F%3E%3Ccircle%20cx%3D%278%27%20cy%3D%2722%27%20r%3D%271.5%27%20fill%3D%27%23333%27%20stroke%3D%27none%27%2F%3E%3C%2Fsvg%3E");

    /* 【第二步】：所有图标原坐标统一 +3px！
       第一个回归 0px，第二个从 32 变 35，后续 79变82... 完美抵消了画框拉大的位移，锁死相对间距！ */
    background-position: 0px center, 35px center, 82px center, 119px center, 156px center, 203px center, 240px center !important;
    background-size: 32px 32px !important; 
    background-repeat: no-repeat !important;
}
/* --- 4. 日记正文排版 (严格 40px 行高，严丝合缝) --- */
.xt-text-diaryTitle {
    font-size: 24px !important; color: #333 !important; text-align: center !important;
    line-height: 40px !important; /* 强制贴合 40px 行高 */
    margin: 10px 0 0 0 !important; padding: 0 !important;
    letter-spacing: 4px !important; 
}

.xt-text-diaryContent {
    font-size: 20px !important; color: #222 !important;
    line-height: 40px !important; /* 强制贴合 40px 行高 */
    margin: 0 !important; padding: 0 16px !important;
    text-indent: 1.5em !important;
    white-space: pre-wrap !important; letter-spacing: 2px !important;
}

.xt-text-diaryEnding {
    font-size: 20px !important; color: #222 !important; text-align: right !important;
    line-height: 40px !important; /* 强制贴合 40px 行高 */
    margin: 0 !important; padding: 0 40px 0 0 !important;
}

/* --- 5. 米字格颜文字区域 (单行锁死防断线 + 稳压底色) --- */
.xt-text-kaomoji {
    display: flex !important; justify-content: center !important; align-items: center !important;
    width: 160px !important; height: 160px !important;

    /* 往下刚好空出 2 行虚线（2 x 40 = 80px）并推到右下角 */
    margin-top: 80px !important; 
    margin-left: auto !important; 
    margin-right: 24px !important;
    margin-bottom: 40px !important;

    /* 【单行锁死防错位】强制单行显示，多出部分隐藏，绝不挤坏网格 */
    font-size: 22px !important; color: #555 !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    padding: 0 8px !important;
    box-sizing: border-box !important;

    /* 强力叠加：底层白色遮盖全局虚线，上层画出不会丢失的 SVG 十字虚线网格 */
    background: #fdfdfd url("data:image/svg+xml;base64,") no-repeat center center / contain !important;
}

/* 1. 优先使用苹果系统自带高质无衬线字体，去除外部网络导入，彻底避免字体加载导致的闪烁与延迟 */
.xt-root {
    --xt-bg: #ffffff;                       /* 纯白备忘录纸张背景 */
    --xt-text: #000000;                     /* 纯黑正文 */
    --xt-text-sub: #8e8e93;                 /* iOS标准灰色时间戳 */
    --xt-accent: #e0a900;                   /* 苹果备忘录经典金黄色 */
    --xt-radius: 24px;                      
    --xt-font: -apple-system, 'SF Pro Display', BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.05); 
    padding: 24px 22px 65px 22px !important; /* 预留底部栏空间 */
    position: relative;
    overflow: hidden;
}

/* 2. 隐藏自带头像（加上最高优先级，防止旧头像先闪出来） */
.xt-header {
    display: none !important;
}

/* 3. 顶部导航栏：左侧“备忘录”，右侧精确复刻【分享箭头圈】与【更多圈】 */
.xt-section {
    margin: 0 0 16px 0 !important;
    position: relative;
}
.xt-section-title {
    color: var(--xt-accent) !important;
    font-size: 17px !important;
    font-weight: 400 !important;
    display: inline-flex;
    align-items: center;
    letter-spacing: -0.4px !important;
    margin-bottom: 0px !important;
}
/* 左侧返回小箭头（苹果官方粗细比例） */
.xt-section-title::before {
    content: "";
    display: inline-block;
    width: 10px;
    height: 10px;
    border-left: 2.5px solid var(--xt-accent);
    border-bottom: 2.5px solid var(--xt-accent);
    transform: rotate(45deg);
    margin-right: 5px;
    margin-top: -1px;
}
/* 右侧：用带有完美线宽的 SVG 矢量图直接绘制苹果官方的“分享”和“更多”按钮 */
.xt-section-title::after {
    content: "";
    position: absolute;
    right: 2px;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    gap: 18px; /* 两个图标的精确间距 */
    width: 64px;
    height: 24px;
    /* 注入纯正的 Apple Share Icon & More Icon 矢量数据 */
    background-image: 
        url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23e0a900" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r=\"10\"/><path d=\"M12 16V8M12 8l-3 3M12 8l3 3\"/></svg>'), 
        url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23e0a900" stroke-width="2"><circle cx="12" cy="12" r=\"10\"/><circle cx=\"8\" cy=\"12\" r=\"1\" fill=\"%23e0a900\"/><circle cx=\"12\" cy=\"12\" r=\"1\" fill=\"%23e0a900\"/><circle cx=\"16\" cy=\"12\" r=\"1\" fill=\"%23e0a900\"/></svg>');
    background-repeat: no-repeat;
    background-size: 23px 23px, 23px 23px;
    background-position: left center, right center;
}

/* 4. 时间戳区域：严格居中，字号缩小，字重降低 */
.xt-section-body {
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    text-align: center !important;
    color: var(--xt-text-sub) !important;
    font-size: 12px !important;
    font-weight: 400;
    margin-top: 6px !important;
    letter-spacing: -0.1px;
}
/* 智能拼装符合中国用户手机习惯的日期格式 */
.xt-section-body::before {
    content: "2026年6月10日 "; 
    display: inline-block;
}

/* 5. 标题：极粗，紧凑排版 */
.xt-text {
    background: transparent !important;
    padding: 16px 0 6px 0 !important;
    color: var(--xt-text) !important;
    font-size: 25px !important;
    font-weight: 800 !important;
    border-radius: 0 !important;
    text-align: left !important;
    letter-spacing: -0.6px;
}

/* 6. 独白文本：严格左对齐，去除括号，优化间距和行高 */
.xt-quote {
    background: transparent !important;
    padding: 2px 0 !important;
    color: #1c1c1e !important;
    font-size: 16px !important;
    line-height: 1.6 !important;
    text-align: left !important;
}
.xt-quote::before, .xt-quote::after {
    display: none !important;              /* 彻底抹除原主题的大括号 */
}

/* 7. 底部工具栏：使用极细的高清线描 SVG 图标，1:1 复刻 iOS 备忘录底部的四个功能按键 */
.xt-root::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 52px;
    background: #ffffff;
    border-top: 0.5px solid #d1d1d6;       /* 苹果标准的极细分割线 */
    padding: 0 24px;
    /* 依次注入：核对清单、相机、手写、新备忘录的官方同款样式 */
    background-image: 
        url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23e0a900" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><path d="m9 11 2 2 4-4"/></svg>'),
        url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23e0a900" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d=\"M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z\"/><circle cx=\"12\" cy=\"13\" r=\"4\"/></svg>'),
        url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill=\"none\" stroke="%23e0a900" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d=\"m12 14 4-4M4 20h16\"/><path d=\"M15 4h5v5M15 9l5-5\"/></svg>'),
        url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="%23e0a900" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d=\"M12 20h9M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z\"/></svg>');
    background-repeat: no-repeat;
    background-size: 22px 22px, 24px 24px, 22px 22px, 21px 21px;
    background-position: 6% center, 36% center, 65% center, 94% center;
}

/* 8. 隐藏不需要的系统脚标组件 */
.xt-footer {
    display: none !important;
}

xinshengCustomPrompt:
At the very END of every reply (after all dialogue), append this as the LAST JSON line. Never reference it in dialogue:
{"t":"xinsheng","innerVoice":"thought character would NEVER say out loud — raw, unguarded, possibly contradicting words, 15-40 Chinese chars","statusText":"(gaze direction OR subconscious body action, 3rd person ≤20 chars, vivid — e.g. 悄悄瞟向你手里的零食 / 飘忽不定不敢对视 / 紧张地抿着嘴唇)","temperature":"36.5°C","emotionLevel":75,"moodDelta":"+3"}
Field rules — innerVoice: PLAIN TEXT ONLY, secret true feeling in Chinese, vivid and honest, distinct from what they said (15-40 chars); statusText: PLAIN TEXT ONLY, WHERE character's eyes land OR involuntary physical tic; temperature: 36°C=calm, rises with excitement/embarrassment, falls with sadness; emotionLevel: 0–100 positive emotion integer; moodDelta: signed integer ("+8", "-5", "0").

xinshengLayout:
# 终极像素级复刻 iOS 备忘录
@header charImage charName .fadeInDown
@section 备忘录
  currentTime
@text noteTitle .fadeInUp.delay100
@quote innerVoice .fadeInUp.delay200
@footer 📄 备忘录已存储

