xinshengCustomCss:
.xt-root {
  --xt-bg: #ffffff;
  --xt-text: #4a4a4a;
  /* 将水蓝色替换为非常浅的淡紫色 */
  --xt-accent: #dcd0ff; 
  --xt-radius: 8px;
  font-size: 13px;
}

/* 头像部分 */
.xt-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
}

/* 投稿卡片：使用极浅的紫罗兰底色和边框 */
.xt-card {
  border: 1px solid #eaddff;
  padding: 12px;
  border-radius: var(--xt-radius);
  background: #fdfaff; /* 非常浅的紫调底色 */
}

.xt-card-title {
  font-size: 11px;
  color: #a894d1;
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* 独立气泡：使用浅紫风格 */
.xt-text {
  background: #fdfaff;
  padding: 8px 12px;
  margin-bottom: 6px;
  border-radius: 6px;
  border-left: 3px solid #dcd0ff; /* 侧边线颜色 */
  color: #555;
  font-size: 14px;
