    /* 强力叠加：底层白色遮盖全局虚线，上层画出不会丢失的 SVG 十字虚线网格 */
    background: #fdfdfd url("data:image/svg+xml;base64,") no-repeat center center / contain !important;
}

/* --- 1. 引入小学生可爱手写字体 --- */
@import url('https://fonts.googleapis.com/css2?family=ZCOOL+KuaiLe&display=swap');

/* --- 2. 全局信纸背景与重置 (恢复圆角 + 页面微拉宽) --- */
.xt-root {
    --xt-bg: #fdfdfd !important;
    font-family: 'ZCOOL KuaiLe', "Chalkboard SE", "Comic Sans MS", cursive, sans-serif !important;
    padding: 0 !important;
    margin: 0 -4px !important; /* 微调页面拉宽，更舒展 */
    width: calc(100% + 8px) !important;

    background-color: var(--xt-bg) !important;
    border-radius: 12px !important; /* 恢复好看的手账圆角 */
    box-shadow: 0 4px 20px rgba(0,0,0,0.06) !important; 

    /* 铺满全屏的虚线信纸背景，严格 40px 一行 */
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg%20width%3D%27100%25%27%20height%3D%2740%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Cline%20x1%3D%270%27%20y1%3D%2739%27%20x2%3D%272000%27%20y2%3D%2739%27%20stroke%3D%27%23d0d0d0%27%20stroke-width%3D%271.5%27%20stroke-dasharray%3D%278%,6%27%2F%3E%3C%2Fsvg%3E") !important;
    background-size: 100% 40px !important;

    /* 【神级对齐】11px偏移量，完美托住汉字的底部基线！ */
    background-position: 0 11px !important; 
}

/* 抹除默认文本的框线 */
.xt-text { background: transparent !important; border: none !important; margin: 0 !important; font-style: normal !important; display: block !important; }

/* --- 3. 顶栏伪装工具条 (固定 50px 高度，带纯实线底部边界) --- */
.xt-text-sysToolbar {
    height: 50px !important; 
    box-sizing: border-box !important;
    background-color: #fdfdfd !important;
    /* 高亮的纯实线边界，利用 z-index 压住底层背景 */
    border-bottom: 1.5px solid #c8c8c8 !important; 
    position: relative !important;
    z-index: 10 !important;
}
/* 左侧：32px 返回箭头 (纯直线段) */
.xt-text-sysToolbar::before {
    content: ""; position: absolute; left: 16px; top: 9px; width: 32px; height: 32px;
    background: url("data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%234a68d6%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22square%22%20stroke-linejoin%3D%22miter%22%3E%3Cpolyline%20points%3D%2215%2018%209%2012%2015%206%22%2F%3E%3C%2Fsvg%3E") center/contain no-repeat;
}

/* 右侧：32px 大图标，【解决边缘被裁切问题】 */
.xt-text-sysToolbar::after {
    content: ""; position: absolute; right: 12px; top: 9px; 

    /* 【第一步】：容器总宽度向左再延伸 3px (286 + 3 = 289px)，彻底包住第一个图标 */
    width: 289px !important; 
    height: 32px; 

    background-image: 
        /* 1. 黑: 键盘 */
