        /* 7. 黑: 列表 */
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20viewBox%3D%270%200%2032%2032%27%20fill%3D%27none%27%20stroke%3D%27%23333%27%20stroke-width%3D%271.5%27%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%3E%3Crect%20x%3D%272%27%20y%3D%272%27%20width%3D%2728%27%20height%3D%2728%27%20rx%3D%276%27%2F%3E%3Cline%20x1%3D%2713%27%20y1%3D%2710%27%20x2%3D%2724%27%20y2%3D%2710%27%20stroke-linecap%3D%27round%27%2F%3E%3Cline%20x1%3D%2713%27%20y1%3D%2716%27%20x2%3D%2724%27%20y2%3D%2716%27%20stroke-linecap%3D%27round%27%2F%3E%3Cline%20x1%3D%2713%27%20y1%3D%2722%27%20x2%3D%2724%27%20y2%3D%2722%27%20stroke-linecap%3D%27round%27%2F%3E%3Ccircle%20cx%3D%278%27%20cy%3D%2710%27%20r%3D%271.5%27%20fill%3D%27%23333%27%20stroke%3D%27none%27%2F%3E%3Ccircle%20cx%3D%278%27%20cy%3D%2716%27%20r%3D%271.5%27%20fill%3D%27%23333%27%20stroke%3D%27none%27%2F%3E%3Ccircle%20cx%3D%278%27%20cy%3D%2722%27%20r%3D%271.5%27%20fill%3D%27%23333%27%20stroke%3D%27none%27%2F%3E%3C%2Fsvg%3E");

    /* 【第二步】：所有图标原坐标统一 +3px！
       第一个回归 0px，第二个从 32 变 35，后续 79变82... 完美抵消了画框拉大的位移，锁死相对间距！ */
    background-position: 0px center, 35px center, 82px center, 119px center, 156px center, 203px center, 240px center !important;
    background-size: 32px 32px !important; 
    background-repeat: no-repeat !important;
